head.script:
scwin.gVar = {
    "cDisabled" : "",
    "cReadOnly" : "",
    "nCount_1" : 0,
    "nCount_2" : 0,
}



// 테스트 설명, 유효성 값 설정
//  - @spec 의 "Event Object 의 설명은 표준 속성만을 다루고 있으며 웹브라우저에 따라 일부 차이가 있을 수 있습니다." 는
//    브라우저 구현 차이에 대한 안내 문구로 확인 수단을 만들 수 없어 유효성에서 제외한다. (secret_E_onblur_1, secret_E_onclick_1 선례)
//  - e 객체의 개별 속성(e.altKey, e.code, e.repeat 등)은 표준 DOM 이벤트 속성이라 개별 유효성으로 만들지 않는다.
//    단 어떤 키를 눌렀는지 구분해야 판정이 가능하므로 e.key 값만 출력에 함께 싣는다.
//  - onkeypress 는 @spec 의 발생 순서 확인용 출력으로만 사용하고, onkeyup 은 연속 발생 출력 카운터 초기화에만 사용한다.
scwin.tData = {
    "description" : "[secret > E > onkeydown]<br/>Secret 컴포넌트 영역에서 키보드의 키를 누를때 발생합니다.",
    "validation" : [
        "Secret 컴포넌트 영역에서 키보드의 키를 누를때 onkeydown 이벤트가 발생합니다.",
        "이벤트 핸들러에 KeyboardEvent 객체 e 가 전달됩니다.",
        "onkeydown 이벤트 발생 시점에는 눌린 키가 입력 영역에 반영되지 않은 상태이므로 이벤트에서 getValue() 메소드 사용 시 이전 입력값이 반환됩니다.",
        "키를 누르고 있으면 onkeydown 이벤트가 연속적으로 발생합니다.",
        "문자에 해당하는 키 입력시 onkeydown 이벤트가 발생한 후 onkeypress 이벤트가 발생합니다.",
        "웹브라우저에 따라 다국어 입력 시 onkeypress 이벤트가 발생하지 않을 수 있습니다.",
        "disabled=true 인 경우 onkeydown 이벤트가 발생하지 않지만 readOnly=true 인 경우엔 onkeydown 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (gdl_boolean 코드값 1 = 미설정)
    con_disabled.setValue("1");
    con_readOnly.setValue("1");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 생성 직후 초기값 secret (6자) 이 설정되며 password 입력창이라 화면에서는 입력값이 마스킹됩니다\n[절차] 조건 선택 후 Target 재생성 -> 결과창 clear -> target1 을 클릭해 포커스를 준 뒤 영문자 키 입력 / 같은 키를 길게 누르기 / 한글 입력을 차례로 시도합니다\n[확인] 각 이벤트는 발생 즉시 한 줄씩 출력되며 연속 발생 시에는 앞 3회까지만 출력하고 ... 로 줄입니다 (키에서 손을 떼면 다시 출력)"', '', 'label1');

    // 출력 카운터 초기화
    scwin.gVar["nCount_1"] = 0;
    scwin.gVar["nCount_2"] = 0;

    // 조건 설정
    scwin.gVar["cDisabled"] = con_disabled.getText();
    scwin.gVar["cReadOnly"] = con_readOnly.getText();

    let properties = {
        disabled : scwin.gVar["cDisabled"],
        readOnly : scwin.gVar["cReadOnly"],
    }

    let cList = $c.gcm.createCList(properties);

    let eList = $c.gcm.createEList(["onkeydown", "onkeypress", "onkeyup"]);

    // comp 생성 함수 호출 (헬퍼가 생성 직후 setValue 로 초기값 secret 설정)
    await $c.gcm.createBasicSecret(cList, eList);
}



// 미설정 표기 변환
scwin.fn_disp = function (strValue) {
    return (strValue === "") ? "미설정" : strValue;
}



// 테스트 샘플의 이벤트 처리 (키 누름) - validation 1, 2, 3, 4, 6, 7 판정 출력
//  - 연속 발생(키를 누르고 있는 경우) 은 앞 3회만 출력하고 3회째에 ... 를 덧붙인다.
scwin.target1_onkeydown = function (e) {
    if (scwin.gVar["nCount_1"] < 3) {
        wf_body_bottom.getObj("scwin").setReturnValue("▶ onkeydown (disabled " + scwin.fn_disp(scwin.gVar["cDisabled"]) + " / readOnly " + scwin.fn_disp(scwin.gVar["cReadOnly"]) + ") key : " + e.key + " -> getValue() : " + target1.getValue());
        wf_body_bottom.getObj("scwin").setReturnValue("e : " + e);

        if (scwin.gVar["nCount_1"] == 2) {
            wf_body_bottom.getObj("scwin").setReturnValue("...");
        }
    }

    scwin.gVar["nCount_1"] += 1;
}



// 발생 순서 확인용 출력 - validation 5, 6 판정 출력 (발생 즉시 한 줄 출력 = 출력 순서가 실제 발생 순서)
scwin.target1_onkeypress = function (e) {
    if (scwin.gVar["nCount_2"] < 3) {
        wf_body_bottom.getObj("scwin").setReturnValue("▶ onkeypress key : " + e.key);

        if (scwin.gVar["nCount_2"] == 2) {
            wf_body_bottom.getObj("scwin").setReturnValue("...");
        }
    }

    scwin.gVar["nCount_2"] += 1;
}



// 연속 발생 출력 카운터 초기화 (출력 없음)
scwin.target1_onkeyup = function (e) {
    scwin.gVar["nCount_1"] = 0;
    scwin.gVar["nCount_2"] = 0;
}
